<?php
require_once '../config/database.php';require_once '../config/session.php';require_once '../includes/term_results.php';require_once '../includes/early_years.php';
if(empty($_SESSION['early_years_family_id'])){header('Location: parent_login.php');exit;}$db=getDBConnection();$familyId=(int)$_SESSION['early_years_family_id'];
$s=$db->prepare('SELECT s.id,s.full_name,s.passport_path,c.name class_name FROM early_years_family_students pc JOIN early_years_students s ON s.id=pc.student_id JOIN early_years_classes c ON c.id=s.class_id WHERE pc.family_id=? ORDER BY s.full_name');$s->bind_param('i',$familyId);$s->execute();$children=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$sessions=termResultsSessionRows($db);$childId=(int)($_GET['student_id']??($children[0]['id']??0));$allowedIds=array_map(static fn($c)=>(int)$c['id'],$children);if(!in_array($childId,$allowedIds,true))$childId=$allowedIds[0]??0;$sessionId=(int)($_GET['session_id']??0);if(!$sessionId)foreach($sessions as $x)if((int)$x['is_current']){$sessionId=(int)$x['id'];break;}if(!$sessionId&&$sessions)$sessionId=(int)$sessions[0]['id'];$term=max(1,min(3,(int)($_GET['term']??1)));$type=($_GET['report_type']??'half_term')==='end_term'?'end_term':'half_term';$report=$childId&&$sessionId?earlyYearsReport($db,$childId,$sessionId,$term,$type):null;$body_class='parent-portal';include '../includes/header.php';
?>
<main class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="small text-uppercase text-primary fw-bold">Early Years</div><h1 class="h3">Family report dashboard</h1><p class="text-muted mb-0">Welcome, <?=htmlspecialchars($_SESSION['early_years_family_label']??'Family')?>.</p></div><a class="btn btn-outline-secondary" href="parent_logout.php">Sign out</a></div>
<?php if(!$children):?><div class="alert alert-info">No pupils are linked to this family code. Contact the school office.</div><?php else:?><form class="card card-body mb-4"><div class="row g-3 align-items-end"><div class="col-md-3"><label class="form-label">Child</label><select class="form-select" name="student_id"><?php foreach($children as $child):?><option value="<?=$child['id']?>" <?=$childId===(int)$child['id']?'selected':''?>><?=htmlspecialchars($child['full_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Session</label><select class="form-select" name="session_id"><?php foreach($sessions as $s):?><option value="<?=$s['id']?>" <?=$sessionId===(int)$s['id']?'selected':''?>><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Term</label><select class="form-select" name="term"><?php for($i=1;$i<=3;$i++):?><option value="<?=$i?>" <?=$term===$i?'selected':''?>><?=htmlspecialchars(termLabel($i))?></option><?php endfor;?></select></div><div class="col-md-2"><label class="form-label">Report</label><select class="form-select" name="report_type"><option value="half_term" <?=$type==='half_term'?'selected':''?>>Half term</option><option value="end_term" <?=$type==='end_term'?'selected':''?>>End of term</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">View report</button></div></div></form>
<?php if($report&&$report['report_data']):?><div class="alert alert-success d-flex justify-content-between align-items-center flex-wrap gap-2"><span><?=htmlspecialchars($report['full_name'])?> · <?=htmlspecialchars($report['session_name']??'')?> · <?=htmlspecialchars(termLabel($term))?> · <?= $type==='half_term'?'Half term':'End of term' ?></span><a class="btn btn-success" href="report.php?student_id=<?=$childId?>&amp;session_id=<?=$sessionId?>&amp;term=<?=$term?>&amp;report_type=<?=htmlspecialchars($type)?>">Open / print report</a></div><?php else:?><div class="alert alert-secondary">This report has not been entered yet.</div><?php endif;?><?php endif;?></main>
<?php include '../includes/footer.php';?>
